param([string]$Unity='C:/Program Files/Unity/Hub/Editor/6000.3.15f1/Editor/Unity.exe')
$ErrorActionPreference='Stop'
$workspaceRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'));$projectRoot=Join-Path $workspaceRoot '.codex-research/RTGIValidation'
$active=Get-CimInstance Win32_Process -Filter "Name='Unity.exe'"|Where-Object{$_.CommandLine -and $_.CommandLine.Replace('\','/').Contains($projectRoot.Replace('\','/'))};if($active){throw 'GI project already active'}
$results=Join-Path $PSScriptRoot 'results';New-Item -ItemType Directory -Force -Path $results|Out-Null
$jobs=@(@{label='qualification';entry='HoRTGIGpuTimestampValidation.Run';report='ho-gi-gpu-qualification/report.json';marker='[HoGIGpuTimestamp] END pass=True'},@{label='256-rg';entry='HoRTGICastleValidation.RunGpu256';report='ho-gi-castle-256-rg-gpu/report.json';marker='[HoGICastle] PASS'},@{label='256-compat';entry='HoRTGICastleValidation.RunGpu256Compatibility';report='ho-gi-castle-256-compat-gpu/report.json';marker='[HoGICastle] PASS'},@{label='512-rg';entry='HoRTGICastleValidation.RunGpu512';report='ho-gi-castle-512-rg-gpu/report.json';marker='[HoGICastle] PASS'},@{label='512-compat';entry='HoRTGICastleValidation.RunGpu512Compatibility';report='ho-gi-castle-512-compat-gpu/report.json';marker='[HoGICastle] PASS'},@{label='256-total-only';entry='HoRTGICastleValidation.RunGpu256TotalOnly';report='ho-gi-castle-256-rg-gpu-total-only/report.json';marker='[HoGICastle] PASS'},@{label='256-rebuild';entry='HoRTGICastleValidation.RunGpu256Rebuild';report='ho-gi-castle-256-rg-gpu-rebuild/report.json';marker='[HoGICastle] PASS'})
$sources=@('Runtime/RTGI/HoRTGIContext.cs','Runtime/RTGI/HoRTGIRendererFeature.cs','Runtime/RTGI/HoRTGICompositePass.cs','Editor/RTGI/HoRTGIGpuClock.cs','Editor/RTGI/HoRTGIGpuTimestampValidation.cs','Editor/RTGI/HoRTGICastleValidation.cs','Editor/RTGI/Shaders/HoRTGIGpuProbe.compute','Tests~/RTGI/GpuTiming/Native/HoGIGpuProbe.cpp')
$records=foreach($source in $sources){@{path=$source;sha256=(Get-FileHash -LiteralPath (Join-Path $workspaceRoot $source)).Hash}}
$run=[ordered]@{step=11;startedUtc=[DateTime]::UtcNow.ToString('o');sources=@($records);nativeBuildSha256=(Get-FileHash -LiteralPath (Join-Path $PSScriptRoot 'native-build.json')).Hash;activeProcess=$null;entries=@()};$runPath=Join-Path $PSScriptRoot 'run.json'
foreach($job in $jobs){
    $started=[DateTime]::UtcNow;$log=Join-Path $workspaceRoot ('.codex-research/rtgi-step011-'+$job.label+'-'+$started.ToString('yyyyMMddTHHmmssfff')+'.log')
    $p=Start-Process -FilePath $Unity -WindowStyle Hidden -PassThru -ArgumentList @('-batchmode','-force-d3d12','-projectPath',('"'+$projectRoot+'"'),'-executeMethod',('lilToon.URP.Extensions.Editor.RTGI.'+$job.entry),'-logFile',('"'+$log+'"'))
    $run.activeProcess=@{id=$p.Id;entry=$job.entry;label=$job.label;log=$log};$run|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $runPath;Write-Output ($job.label+' PID '+$p.Id)
    $p.WaitForExit();$report=Join-Path $projectRoot $job.report
    $record=[ordered]@{label=$job.label;exitCode=$p.ExitCode;log=$log;logSha256=(Get-FileHash -LiteralPath $log).Hash;marker=@(Select-String -LiteralPath $log -SimpleMatch $job.marker).Count -gt 0;fresh=(Test-Path -LiteralPath $report) -and (Get-Item -LiteralPath $report).LastWriteTimeUtc -ge $started;shaderCsDiagnostics=@(Select-String -LiteralPath $log -Pattern 'Shader error|Shader warning|error CS').Count}
    if($record.fresh){$data=Get-Content -LiteralPath $report -Raw|ConvertFrom-Json;$record.pass=$data.pass;$record.reportSha256=(Get-FileHash -LiteralPath $report).Hash;Copy-Item -LiteralPath $report -Destination (Join-Path $results ($job.label+'.json'))}
    $run.entries+=$record;$run.activeProcess=$null;$run|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $runPath;Write-Output ($job.label+' exit '+$p.ExitCode+' pass='+$record.pass)
    if($p.ExitCode -ne 0 -or -not $record.marker -or -not $record.fresh -or -not $record.pass -or $record.shaderCsDiagnostics -ne 0){throw ('GPU timestamp validation failed: '+$job.label)}
}
